content.query:
SecurityIncident
| where TimeGenerated {TimeRange}
| where IncidentNumber == {SelectedIncident}
| summarize arg_max(TimeGenerated, *) by IncidentNumber
| extend DefenderUrl = strcat("https://security.microsoft.com/incidents/", tostring(IncidentNumber), "?tid=", TenantId)
| project Incident = IncidentNumber, Title, Severity, Status, DefenderUrl, IncidentUrl

// Exactly two columns: label, number. A datetime column would switch
// this into time-series mode and the bars would vanish.
SecurityAlert
| where TimeGenerated {TimeRange}
| where AlertSeverity in ({Severity})
| where "{Rule}" == "All" or AlertName == "{Rule}"
| where "{Provider}" == "All" or ProductName has "{Provider}"
| summarize Alerts = count() by Rule = AlertName
| top 10 by Alerts desc

// Two tables side by side -- recipe P6.
let Alerts =
    SecurityAlert
    | where TimeGenerated {TimeRange}
    | summarize Alerts = count() by Rule = AlertName;
let Incidents =
    SecurityIncident
    | where TimeGenerated {TimeRange}
    | summarize arg_max(TimeGenerated, *) by IncidentNumber
    | summarize Incidents = count(),
                HighSev = countif(Severity == "High") by Rule = Title;
Alerts
| join kind=leftouter Incidents on Rule
| extend Incidents = coalesce(Incidents, long(0))
| extend HighSev = coalesce(HighSev, long(0))
| extend ConversionPct = round(100.0 * Incidents / Alerts, 1)
| extend Verdict = case(Alerts >= 100 and ConversionPct < 10, "Noisy - tuning candidate",
                        ConversionPct >= 80, "Converts well",
                                             "Normal")
| project Rule, Alerts, Incidents, HighSev, ConversionPct, Verdict
| order by Alerts desc
| take 20

// Run this first. It tells you which panels below can work at all.
union isfuzzy=true
  (BehaviorAnalytics | where TimeGenerated {TimeRange}
     | summarize Rows = count(), Users = dcount(UserPrincipalName)
     | extend Source = "BehaviorAnalytics (UEBA)"),
  (Anomalies | where TimeGenerated {TimeRange}
     | summarize Rows = count(), Users = dcount(UserPrincipalName)
     | extend Source = "Anomalies (UEBA models)"),
  (AADRiskyUsers | where TimeGenerated {TimeRange}
     | summarize Rows = count(), Users = dcount(UserPrincipalName)
     | extend Source = "AADRiskyUsers (Entra ID Protection)")
| extend Status = iff(Rows > 0, "Available", "No data - connector or feature not enabled")
| project Source, Rows, Users, Status

// AADRiskyUsers logs an update per change, so de-duplicate to the
// newest row per user -- same idea as SecurityIncident.
AADRiskyUsers
| where TimeGenerated {TimeRange}
| summarize arg_max(TimeGenerated, *) by UserPrincipalName
| where IsDeleted == false
| where RiskLevel in ("low", "medium", "high")
| summarize Users = count() by RiskLevel
| order by Users desc

// AADRiskyUsers logs an update per change, so de-duplicate to the
// newest row per user -- same idea as SecurityIncident.
AADRiskyUsers
| where TimeGenerated {TimeRange}
| summarize arg_max(TimeGenerated, *) by UserPrincipalName
| where IsDeleted == false
| where RiskLevel in ("low", "medium", "high")
| summarize Users = count() by RiskLevel
| order by Users desc

// Uses {RiskTrendRange} -- the buttons above this chart, not the page filter.
AADRiskyUsers
| where TimeGenerated {RiskTrendRange}
| where RiskLevel in ("low", "medium", "high")
| summarize Users = dcount(UserPrincipalName) by bin(TimeGenerated, 1d), RiskLevel
| order by TimeGenerated asc

// Same join as the panel above, with one extra filter -- P2 applied
// to a P6 query.
let IncidentUsers =
    SecurityIncident
    | where TimeGenerated {TimeRange}
    | where Severity in ({Severity})
    | summarize arg_max(TimeGenerated, *) by IncidentNumber
    | mv-expand AlertId = AlertIds to typeof(string)
    | join kind=inner (
        SecurityAlert
        | where TimeGenerated {TimeRange}
        | where isnotempty(CompromisedEntity)
        | project SystemAlertId, CompromisedEntity, AlertName
      ) on $left.AlertId == $right.SystemAlertId;
IncidentUsers
| where Severity == "High"
| where "{User}" == "All" or CompromisedEntity has "{User}"
| summarize HighSevIncidents = dcount(IncidentNumber),
            Rules = dcount(AlertName),
            LastSeen = max(CreatedTime) by User = CompromisedEntity
| order by HighSevIncidents desc
| take 25
